package dev.thor.galaxy;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.zip.*;
public class Transactions {
 static int checks;static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;}
 static void put(Path root,String name,String text)throws Exception{Path p=root.resolve(name);Files.createDirectories(p.getParent());Files.write(p,text.getBytes("UTF-8"));}
 static String read(Path p)throws Exception{return new String(Files.readAllBytes(p),"UTF-8");}
 static Path fixture(Path root,String name,String value)throws Exception{Path d=root.resolve(name);for(String part:new String[]{"files","sys","ThorHud"})put(d,part+"/value",value);put(d,"ThorHud/SETUP-MANIFEST.json","{}");return d;}
 static byte[] backup(boolean bad,boolean traversal)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();Properties manifest=new Properties();Map<String,String> entries=new LinkedHashMap<>();entries.put("internal/nand/settings.ini","owner-settings");entries.put("internal/nand/title/00010000/524d4745/data/GameData.bin","owner-save");for(String s:new String[]{"sys/fst.bin","files/ObjectData/Coin.arc","ThorHud/SETUP-MANIFEST.json","ThorHud/planets/HeavensDoorGalaxy.planets",".ready"})entries.put("external/GalaxyData/"+s,"CRAR-fixture");if(traversal)entries.put("external/GalaxyData/../../escape","bad");try(ZipOutputStream zip=new ZipOutputStream(bytes)){for(Map.Entry<String,String> e:entries.entrySet()){byte[] data=e.getValue().getBytes("UTF-8");zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(data);zip.closeEntry();StringBuilder h=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(data))h.append(String.format("%02x",b&255));manifest.setProperty(e.getKey(),bad?"bad":h.toString());}ByteArrayOutputStream m=new ByteArrayOutputStream();manifest.store(m,"fixture");zip.putNextEntry(new ZipEntry("BACKUP-MANIFEST.properties"));zip.write(m.toByteArray());zip.closeEntry();}return bytes.toByteArray();}
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("wiids-galaxy-transactions-");
  for(int fail=0;fail<7;fail++){Path t=root.resolve("fault-"+fail);Path data=fixture(t,"GalaxyData","old"),pending=fixture(t,"GalaxyData.pending","new");put(data,".ready","old-ready");put(data,"saves/GameData.bin","owner-save");final int at=fail;final int[] n={0};boolean threw=false;try{GalaxyInstall.install(data.toFile(),pending.toFile(),(a,b)->{if(n[0]++==at)throw new IOException("Injected move failure");});}catch(IOException expected){threw=true;}check(threw,"injected failure propagates");for(String p:new String[]{"files","sys","ThorHud"})check(read(data.resolve(p+"/value")).equals("old"),"rollback "+p);check(read(data.resolve(".ready")).equals("old-ready"),"readiness restored");check(read(data.resolve("saves/GameData.bin")).equals("owner-save"),"save preserved");GalaxyInstall.recover(data.toFile());check(!Files.exists(t.resolve(".galaxy-install.properties")),"journal closed");}
  Path t=root.resolve("success"),data=fixture(t,"GalaxyData","old"),pending=fixture(t,"GalaxyData.pending","new");put(data,"saves/GameData.bin","owner-save");GalaxyInstall.install(data.toFile(),pending.toFile());for(String p:new String[]{"files","sys","ThorHud"})check(read(data.resolve(p+"/value")).equals("new"),"new parts published");check(read(data.resolve("saves/GameData.bin")).equals("owner-save"),"save survives success");check(!Files.exists(pending),"pending cleaned");
  for(int mode=0;mode<3;mode++){Path i=root.resolve("migration-"+mode+"/internal"),e=root.resolve("migration-"+mode+"/external");Files.createDirectories(i);Files.createDirectories(e);boolean threw=false;try{GalaxyMigration.importBackup(i.toFile(),e.toFile(),new ByteArrayInputStream(backup(mode==1,mode==2)));}catch(Exception expected){threw=true;}check(threw==(mode!=0),"backup outcome");check(!GalaxyMigration.pending(i.toFile()),"migration journal closed");if(mode==0){check(read(i.resolve("nand/settings.ini")).equals("owner-settings"),"settings copied exactly");check(read(i.resolve("nand/title/00010000/524d4745/data/GameData.bin")).equals("owner-save"),"save copied exactly");boolean refused=false;try{GalaxyMigration.importBackup(i.toFile(),e.toFile(),new ByteArrayInputStream(backup(false,false)));}catch(IOException expected){refused=true;}check(refused,"existing profile never overwritten");}else{check(!Files.exists(i.resolve("nand")),"failed backup leaves no NAND");check(!Files.exists(e.resolve("GalaxyData")),"failed backup leaves no game profile");}}
  System.out.println("PASS: "+checks+" actual-source transaction/migration assertions; seven injected move failures, checksum mismatch and traversal rejected");
 }
}
